file:/runs/kit/REQ-001/ci/INTEGRITY_EVAL.json
{
  "version": "1.0",
  "req_id": "REQ-001",
  "verdict": "reject",
  "hardening_required": true,
  "summary": "Candidate is in the correct Data/sql lane and roughly the correct module family, but it implements the wrong schema and lifecycle contract for REQ-001. Most core entities, enum values, transitions, and audit fields diverge materially from the required canonical Slice-1 backbone. Tests and docs reinforce the wrong semantics, so this is not promotion-plausible as-is.",
  "scope_fidelity": {
    "score": 2,
    "out_of": 25,
    "assessment": "Low. The candidate creates eight tables and an Alembic baseline, but the actual contract is largely wrong. Document lifecycle states are not the required uploaded/processing/validation_ready/exception/validated/(reserved exported); instead it defines uploaded/ingesting/extracted/validated/archived/failed and then forbids all document transitions. User, Document, ExtractedField, Task, Notification, ExportJob, AuditEvent, and AIQuery field sets do not match the REQ contract."
  },
  "lane_fidelity": {
    "score": 10,
    "out_of": 15,
    "assessment": "Moderate. This is clearly a Data/sql-lane submission using SQLAlchemy and Alembic under the permitted data module family. Lane choice is correct, but the implementation semantics are for a different lifecycle model than the declared REQ."
  },
  "path_contract": {
    "score": 7,
    "out_of": 10,
    "assessment": "Mostly localized correctly under src/data/schema and src/data/migrations, with tests under the staged test tree. There is mild contract drift versus plan.json's expected pluralized test root, though the manifest and repository evidence make the chosen test root repo-fit. Path correctness does not offset the semantic mismatch."
  },
  "source_substance": {
    "score": 5,
    "out_of": 20,
    "assessment": "There is non-trivial source substance: enums, transition helpers, metadata, tables, indexes, migration, and audit immutability trigger. However, the substance is mostly aimed at the wrong domain contract. Key required invariants are absent or replaced with incompatible ones: username uniqueness per deployment profile, active flag, document size/format checks, validation task semantics, explicit notification/export/AI lifecycles, preserved validated_by/validated_at fields, and audit before/after/reason fields."
  },
  "test_substance": {
    "score": 3,
    "out_of": 15,
    "assessment": "Tests are present and executable in shape, but they mainly verify the wrong contract. Unit tests assert incorrect enum values and transition rules. Integration tests check table creation, some indexes, and audit immutability, but do not verify the required REQ-001 lifecycle states, reserved exported handling, required field set, or business invariants. The e2e test only exercises a Python helper, not a schema-enforced lifecycle rule."
  },
  "docs_ci_coherence": {
    "score": 1,
    "out_of": 5,
    "assessment": "Low coherence. Docs and CI are internally aligned with the candidate, but they overclaim REQ fidelity. README/KIT docs state Document.state exported is present/reserved, while the source enum does not include exported. Documentation reinforces incorrect behavior rather than accurately constraining it."
  },
  "repo_fit": {
    "score": 6,
    "out_of": 10,
    "assessment": "Reasonable repository fit in terms of localization and promotion staging. No forbidden backend/frontend/infra families were touched. But promotion would inject a semantically incompatible canonical schema into the repo, which is a stop-ship issue for fit with downstream REQs."
  },
  "blockers": [
    "Wrong Document lifecycle contract: required states are uploaded, processing, validation_ready, exception, validated, with exported reserved in schema only. Candidate defines incompatible states and then blocks all document transitions wholesale.",
    "Wrong ExtractedField lifecycle contract: required proposed/corrected/accepted/rejected is replaced by pending/extracted/reviewed/accepted/rejected/failed.",
    "Wrong Task lifecycle contract: required open/in_progress/completed/exception is replaced by queued/running/succeeded/failed/cancelled.",
    "Wrong Notification lifecycle contract: required pending/sent/failed/read is replaced by pending/dispatched/delivered/read/failed.",
    "Wrong ExportJob lifecycle contract: required requested/running/completed/failed is replaced by queued/running/completed/failed/cancelled.",
    "Wrong AIQuery lifecycle contract: required requested/completed/denied/failed is replaced by queued/running/answered/failed/cancelled.",
    "Core entity schemas do not match REQ-001 data contracts. Examples: User lacks username and active; Document lacks original_filename/format/size_bytes/storage_uri/uploaded_by/uploaded_at/validated_by/validated_at; ExtractedField lacks proposed_value/corrected_value/provenance/updated_by; Notification lacks document_id and notification_type; AIQuery lacks citations and uses nullable document_id plus prompt-search fields not required by the contract.",
    "AuditEvent contract is wrong. Required actor_id, before_value, after_value, and reason fields are missing; payload plus actor_type/actor_identifier is not the declared canonical schema.",
    "Required invariants are missing or incompatible: no document size <= 20 MB check, no format enum restriction, no confidence_score normalization check, no task_type fixed to validation, no one-task-per-document validation invariant, no completed-task linkage semantics.",
    "Search-supporting index strategy is not the requested one. Candidate adds generic JSONB and AI prompt indexes instead of the canonical metadata-field/full-text support expected for later archive requirements.",
    "Tests and docs codify the incorrect schema and lifecycle, so they cannot be used as evidence for REQ-001 acceptance."
  ],
  "hardening_targets": [
    {
      "path": "runs/kit/REQ-001/src/data/schema/core_lifecycle.py",
      "required": "Replace the enum sets, transition matrix, and table definitions with the exact REQ-001 canonical contracts. This is a substantive rewrite, not a small patch."
    },
    {
      "path": "runs/kit/REQ-001/src/data/migrations/versions/0001_req001_canonical_schema.py",
      "required": "Rebuild the migration to match the required entities, fields, constraints, indexes, and audit append-only behavior."
    },
    {
      "path": "runs/kit/REQ-001/test/data/schema/test_core_lifecycle_unit.py",
      "required": "Rewrite unit assertions against the actual REQ-001 states, forbidden transitions, unique constraints, and invariant definitions."
    },
    {
      "path": "runs/kit/REQ-001/test/data/schema/test_migrations_integration.py",
      "required": "Add contract-accurate upgrade/downgrade verification for required columns, constraints, and index strategy; remove assertions tied to the wrong schema."
    },
    {
      "path": "runs/kit/REQ-001/test/data/schema/test_document_transition_e2e.py",
      "required": "Reframe e2e evidence around the required lifecycle semantics, especially allowed uploaded->processing and forbidden uploaded->validated, plus reserved exported handling."
    },
    {
      "path": "runs/kit/REQ-001/docs/KIT_REQ-001.md",
      "required": "Correct overclaims and document only behavior actually implemented by the canonical REQ-001 contract."
    },
    {
      "path": "runs/kit/REQ-001/docs/README_REQ-001.md",
      "required": "Align documentation with the actual required schema and lifecycle backbone; remove false statement that exported is present in the current source."
    }
  ],
  "promotability_score": 34
}
